import './style.css';

const app = document.querySelector('#app');
const state = {
  config: {}, categories: [], products: [], cart: readCart(), category: 'all', query: '',
  admin: false, adminEmail: '', adminTab: 'overview', adminOrders: [], adminProducts: [], adminCategories: [],
};
const fmt = (n) => `৳${Number(n || 0).toLocaleString('en-BD')}`;
const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (s='') => { try { const u=new URL(s); return ['https:','http:'].includes(u.protocol) ? u.href : ''; } catch { return ''; } };
const bdDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function readCart(){ try{return JSON.parse(localStorage.getItem('nawab_cart')||'[]')}catch{return []} }
function saveCart(){ localStorage.setItem('nawab_cart',JSON.stringify(state.cart)); }
async function api(url, options={}) {
  const response=await fetch(url,{credentials:'same-origin',...options});
  const type=response.headers.get('content-type')||'';
  const data=type.includes('application/json')?await response.json():null;
  if(!response.ok) throw new Error(data?.error||`Request failed (${response.status})`);
  return data;
}
const jsonOptions=(body)=>({method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
const productImage=(p)=>p.image_url ? `<img src="${esc(safeUrl(p.image_url))}" alt="${esc(p.title)}" loading="lazy" onerror="this.remove()">` : `<div class="fabric-art ${p.category_slug==='lungi'?'fabric-lungi':'fabric-saree'}"><span>${p.category_slug==='lungi'?'লুঙ্গি':'শাড়ি'}</span></div>`;

async function loadStore(){
  try { state.config=await api('/api/config'); const productRoute=location.pathname.match(/^\/products\/(\d+)\/?$/); const params=new URLSearchParams(location.search); if(params.has('category'))state.category=params.get('category')||'all'; const data=await api(`/api/products?category=${encodeURIComponent(productRoute?'all':state.category)}&q=${encodeURIComponent(state.query)}`); state.products=data.products; state.categories=data.categories; if(productRoute){await openProduct(Number(productRoute[1]),{push:false});return} renderStore(); }
  catch(e){ app.innerHTML=`<main class="offline"><div class="monogram">NL</div><h1>Store setup চলছে</h1><p>${esc(e.message)}<br>Turso database-এর সংযোগ ঠিক আছে কি না দেখুন।</p><a href="#admin">Admin setup</a></main>`; }
}
function cartCount(){return state.cart.reduce((n,row)=>n+row.quantity,0)}
function cartTotal(){return state.cart.reduce((n,row)=>n+(Number(row.price)||0)*row.quantity,0)}
function categoryLink(c){return `<button class="nav-link ${state.category===c.slug?'is-current':''}" data-category="${esc(c.slug)}">${esc(c.name)}</button>`}
function productCard(p,i){return `<article class="product-card" data-open-product="${p.id}" style="--delay:${i*45}ms"><button class="product-visual" aria-label="${esc(p.title)} এর বিস্তারিত">${productImage(p)}${p.featured?'<span class="tag">পছন্দের</span>':''}<span class="quick-add">বিস্তারিত দেখুন <span>↗</span></span></button><div class="product-meta"><span class="eyebrow">${esc(p.category_name||'নতুন সংগ্রহ')}</span><h3>${esc(p.title)}</h3><div class="price-row"><strong>${fmt(p.price)}</strong>${p.compare_at?`<del>${fmt(p.compare_at)}</del>`:''}<span class="stock">${p.stock>0?'স্টকে আছে':'স্টক শেষ'}</span></div></div></article>`}
function storeFooter(cfg){return `<footer class="store-footer" id="contact"><section class="footer-newsletter"><div><h2>NEWSLETTER SIGN UP</h2><p>নতুন সংগ্রহ, অফার ও আরও খবর পেতে ইমেইল দিন।</p></div><form class="newsletter-form" id="newsletter-form"><input type="email" name="email" placeholder="ইমেইল ঠিকানা" aria-label="ইমেইল ঠিকানা" required><button aria-label="সাবস্ক্রাইব করুন"><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button></form><div class="footer-socials" aria-label="সামাজিক মাধ্যম"><a href="#contact-options" aria-label="X" title="X"><i class="fa-brands fa-x-twitter" aria-hidden="true"></i></a><a href="${esc(safeUrl(cfg.facebook)||'#contact-options')}" aria-label="Facebook" title="Facebook"><i class="fa-brands fa-facebook-f" aria-hidden="true"></i></a><a href="${esc(safeUrl(cfg.instagram)||'#contact-options')}" aria-label="Instagram" title="Instagram"><i class="fa-brands fa-instagram" aria-hidden="true"></i></a><a href="#contact-options" aria-label="YouTube" title="YouTube"><i class="fa-brands fa-youtube" aria-hidden="true"></i></a></div></section><div class="footer-columns"><div><h3>SHOP</h3><a href="#collection">সব পণ্য</a>${state.categories.map(c=>`<a href="/?category=${esc(c.slug)}#collection">${esc(c.name)}</a>`).join('')}</div><div><h3>INFORMATION</h3><a href="#about">About Us</a><a href="#contact-options">Contact Us</a><a href="#about">আমাদের গল্প</a></div><div><h3>CUSTOMER SERVICE</h3><a href="#about">ডেলিভারি তথ্য</a><a href="#about">রিটার্ন ও এক্সচেঞ্জ</a><a href="#contact-options">যোগাযোগ ও সহায়তা</a><a href="#about">গোপনীয়তা নীতি</a></div></div><div class="footer-brand-row"><a class="footer-wordmark" href="#home">${esc(cfg.store_name||'নওয়াব লুম').toUpperCase()}</a><span>© ${new Date().getFullYear()} · সর্বস্বত্ব সংরক্ষিত</span></div></footer>`}
function contactItems(){const c=state.config;return [{cls:'wa',label:'WhatsApp',url:c.whatsapp?`https://wa.me/${c.whatsapp.replace(/\D/g,'')}`:'',icon:'fa-brands fa-whatsapp'},{cls:'fb',label:'Facebook',url:c.facebook||'',icon:'fa-brands fa-facebook-f'},{cls:'ig',label:'Instagram',url:c.instagram||'',icon:'fa-brands fa-instagram'},{cls:'call',label:'Call',url:c.phone?`tel:${c.phone}`:'',icon:'fa-solid fa-phone'}];}
function contactRail(){return `<aside class="contact-widget" aria-label="যোগাযোগ"><div class="contact-options" id="contact-options" hidden>${contactItems().map(item=>item.url?`<a class="rail-${item.cls}" href="${esc(safeUrl(item.url)||item.url)}" target="${item.url.startsWith('http')?'_blank':'_self'}" rel="noopener" aria-label="${item.label}" title="${item.label}"><i class="${item.icon}" aria-hidden="true"></i><span>${item.label}</span></a>`:`<span class="rail-${item.cls} contact-disabled" aria-disabled="true" title="Admin settings-এ ${item.label} যোগ করুন"><i class="${item.icon}" aria-hidden="true"></i><span>${item.label}</span></span>`).join('')}</div><button class="contact-toggle" type="button" aria-expanded="false" aria-controls="contact-options"><i class="fa-regular fa-comment-dots" aria-hidden="true"></i><span>যোগাযোগ</span></button></aside>`}
function renderStore(){
  const cfg=state.config;document.title=`${cfg.store_name||'নওয়াব লুম'} — শাড়ি ও লুঙ্গি`;const categoryName=state.category==='all'?'জনপ্রিয় সংগ্রহ':state.categories.find(c=>c.slug===state.category)?.name||'পণ্য সংগ্রহ';
  app.innerHTML=`<div class="design-promo"><div><span>✦ বাছাই করা কাপড়</span><span>✦ সারা বাংলাদেশে ডেলিভারি</span><span>✦ সহজ রিটার্ন ও এক্সচেঞ্জ</span></div><div class="design-promo-right">ঐতিহ্যের বুনন · যত্নের সংগ্রহ</div></div>
  <header class="site-header design-header"><a class="design-logo" href="#home" aria-label="${esc(cfg.store_name||'নওয়াব লুম')}"><img src="/img/logo.jpg" alt="${esc(cfg.store_name||'নওয়াব লুম')}" onerror="this.onerror=null;this.outerHTML='<span class=\'brand-mark\'>NL</span>'"></a><label class="search-box design-search"><span><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i></span><input id="search" placeholder="শাড়ি বা লুঙ্গি খুঁজুন" value="${esc(state.query)}" aria-label="পণ্য খুঁজুন"><kbd>⌘ K</kbd></label><div class="header-actions design-header-actions"><span class="design-phone">${cfg.phone?`<a href="tel:${esc(cfg.phone)}">${esc(cfg.phone)}</a><small>যেকোনো সময় কল করুন</small>`:'সারাদেশে ডেলিভারি'}</span><button class="bag-button design-bag" id="open-cart" aria-label="ব্যাগ"><i class="fa-solid fa-bag-shopping" aria-hidden="true"></i><span>ব্যাগ</span><b>${cartCount()}</b></button><button class="mobile-menu" id="mobile-menu" aria-label="মেনু">☰</button></div></header>
  <nav class="design-nav"><button class="nav-link ${state.category==='all'?'is-current':''}" data-category="all">সব পণ্য</button>${state.categories.map(categoryLink).join('')}<a class="nav-link" href="#collection">নতুন সংগ্রহ</a><a class="nav-link" href="#about">আমাদের কথা</a><a class="nav-link" href="#contact-options">যোগাযোগ</a></nav>
  <main id="home"><section class="design-hero"><div class="design-hero-copy"><span class="design-kicker">PREMIUM COLLECTION</span><h1>শাড়ি ও লুঙ্গি</h1><h2>ঐতিহ্যের প্রতিটি সুতায়</h2><p>${esc(cfg.tagline||'বাংলার বুননে, আপন সাজে')} — প্রতিদিনের জন্য যত্নে বাছাই করা সংগ্রহ।</p><button class="design-shop" data-category="all">সংগ্রহ দেখুন <span>→</span></button></div><img class="design-hero-image" src="/img/hero.jpg" alt="শাড়ি ও লুঙ্গির সংগ্রহ"></section>
  <section class="design-categories">${state.categories.map(c=>`<button class="design-category" data-category="${esc(c.slug)}"><span class="design-category-copy"><strong>${esc(c.name)} সংগ্রহ</strong><em>${c.slug==='lungi'?'প্রতিদিনের আরাম':'প্রতিটি সাজে আভিজাত্য'}</em><small>সংগ্রহ দেখুন →</small></span><img src="${c.slug==='lungi'?'/img/lungi.jpg':'/img/saree.jpg'}" alt="${esc(c.name)} সংগ্রহ" loading="lazy"></button>`).join('')}</section>
  <section class="design-trust"><div><i class="fa-regular fa-gem" aria-hidden="true"></i><span>প্রিমিয়াম মান<br><small>যত্নে বাছাই করা</small></span></div><div><i class="fa-solid fa-truck-fast" aria-hidden="true"></i><span>দ্রুত ডেলিভারি<br><small>সারা বাংলাদেশে</small></span></div><div><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><span>নিরাপদ পেমেন্ট<br><small>bKash, Nagad ও আরও</small></span></div><div><i class="fa-solid fa-money-bill-wave" aria-hidden="true"></i><span>Cash on Delivery<br><small>সহজ অর্ডার</small></span></div></section>
  <section class="collection-section design-collection" id="collection"><div class="section-heading"><div><span class="eyebrow">কাপড়ের গল্প</span><h2>${esc(categoryName)}</h2></div><div class="collection-tools"><span>${state.products.length}টি পণ্য</span><select id="sort" aria-label="পণ্য সাজান"><option value="featured">সাজানো</option><option value="price_asc">দাম: কম থেকে বেশি</option><option value="price_desc">দাম: বেশি থেকে কম</option></select></div></div><div class="product-grid design-products">${state.products.length?state.products.map(productCard).join(''):'<div class="empty-products"><span>✳</span><h3>এই সংগ্রহে এখনো পণ্য নেই</h3><p>Admin panel থেকে পণ্য যোগ করলে এখানে দেখা যাবে।</p><a href="#admin">Admin panel</a></div>'}</div></section>
  <section class="about-section" id="about"><div class="about-content"><span class="eyebrow">ABOUT US · আমাদের কথা</span><h2>কাপড়ের প্রতিটি সুতায় যত্ন।</h2><p>${esc(cfg.about||'বাংলার ঐতিহ্যবাহী বুনন আর প্রতিদিনের আরামের মাঝে আমরা খুঁজে নিই আমাদের সংগ্রহ। প্রতিটি পণ্য বাছাই করা হয় যত্ন নিয়ে, যেন আপনার কাছে পৌঁছায় সুন্দরভাবে।')}</p><a href="#contact-options" class="under-link">আমাদের সাথে কথা বলুন <span>↗</span></a></div></section>
  ${storeFooter(cfg)}</main>${contactRail()}<div id="modal-root"></div>`;
  bindStoreEvents();bindContactWidget();
}
function bindContactWidget(){const button=app.querySelector('.contact-toggle'),links=app.querySelector('#contact-options');const show=()=>{if(!button||!links)return;button.setAttribute('aria-expanded','true');links.hidden=false};button?.addEventListener('click',()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));links.hidden=expanded});app.querySelectorAll('a[href="#contact-options"]').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();show();app.querySelector('.contact-widget')?.scrollIntoView({behavior:'smooth',block:'center'})}))}
function bindStoreEvents(){
  app.querySelectorAll('[data-category]').forEach(el=>el.addEventListener('click',()=>{state.category=el.dataset.category;loadStore();document.querySelector('#collection')?.scrollIntoView({behavior:'smooth'});}));
  app.querySelector('#search')?.addEventListener('input',e=>{state.query=e.target.value;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(async()=>{try{const d=await api(`/api/products?category=${encodeURIComponent(state.category)}&q=${encodeURIComponent(state.query)}`);state.products=d.products;state.categories=d.categories;const grid=document.querySelector('.product-grid');if(grid)grid.innerHTML=state.products.map(productCard).join('')||'<div class="empty-products"><span>✳</span><h3>এই সংগ্রহে এখনো পণ্য নেই</h3><p>Admin panel থেকে পণ্য যোগ করলে এখানে দেখা যাবে।</p></div>';const count=document.querySelector('.collection-tools span');if(count)count.textContent=`${state.products.length}টি পণ্য`;document.querySelectorAll('[data-open-product]').forEach(el=>el.addEventListener('click',()=>openProduct(Number(el.dataset.openProduct))))}catch(err){toast(err.message)}},260)});
  app.querySelector('#sort')?.addEventListener('change',async e=>{const d=await api(`/api/products?category=${encodeURIComponent(state.category)}&q=${encodeURIComponent(state.query)}&sort=${e.target.value}`);state.products=d.products;state.categories=d.categories;renderStore()});
app.querySelector('#open-cart')?.addEventListener('click',openCart);app.querySelector('#mobile-menu')?.addEventListener('click',()=>app.querySelector('.design-nav')?.classList.toggle('nav-open'));
  app.querySelectorAll('[data-open-product]').forEach(el=>el.addEventListener('click',()=>openProduct(Number(el.dataset.openProduct))));
  app.querySelectorAll('a[href="#admin"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();location.hash='admin';renderAdmin()}));
  app.querySelectorAll('a[href="#home"]').forEach(a=>a.addEventListener('click',()=>{state.category='all';loadStore()}));
  document.addEventListener('keydown',searchShortcut,{once:true});
}
function searchShortcut(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search')?.focus()}document.addEventListener('keydown',searchShortcut,{once:true})}
function openModal(html){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal-shell">${html}<button class="modal-close" aria-label="বন্ধ করুন">×</button></section></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''});root.querySelector('.modal-close').addEventListener('click',()=>root.innerHTML='');}
async function openProduct(id,{push=true}={}){
  try{
    const {product:p,related=[]}=await api(`/api/products?id=${id}`);if(!p)throw new Error('পণ্যটি পাওয়া যায়নি।');
    if(push)history.pushState({productId:p.id},'',`/products/${p.id}`);
    document.title=`${p.title} — ${state.config.store_name||'নওয়াব লুম'}`;
    app.innerHTML=`<header class="site-header"><a class="brand" href="/"><span class="brand-mark">NL</span><span><strong>${esc(state.config.store_name||'নওয়াব লুম')}</strong><small>বাংলার বুনন · যত্নের সংগ্রহ</small></span></a><nav class="desktop-nav"><a class="nav-link" href="/#collection">সব পণ্য</a>${state.categories.map(c=>`<a class="nav-link" href="/?category=${esc(c.slug)}#collection">${esc(c.name)}</a>`).join('')}<a class="nav-link" href="/#about">আমাদের কথা</a></nav><div class="header-actions"><a class="text-button product-home-link" href="/">দোকানে ফিরুন</a><button class="bag-button" id="open-cart" aria-label="ব্যাগ"><span>ব্যাগ</span><i class="fa-solid fa-bag-shopping" aria-hidden="true"></i><b>${cartCount()}</b></button></div></header><main class="product-page"><a class="product-back" href="/">← সব পণ্য</a><div class="product-breadcrumb">${esc(p.category_name||'পণ্য')} <span>/</span> ${esc(p.title)}</div><section class="product-detail product-detail-page"><div class="detail-visual">${productImage(p)}<span class="detail-index">NL / ${String(p.id).padStart(2,'0')}</span></div><div class="detail-copy"><span class="eyebrow">${esc(p.category_name)} · বাছাই করা</span><h1>${esc(p.title)}</h1><p class="detail-price">${fmt(p.price)} ${p.compare_at?`<del>${fmt(p.compare_at)}</del>`:''}</p><p class="detail-description">${esc(p.description)}</p><p class="detail-stock">${p.stock>0?`● স্টকে আছে · ${p.stock}টি`:'○ স্টক শেষ'}</p><div class="qty-control"><span>পরিমাণ</span><button id="qty-minus" type="button">−</button><b id="detail-qty">1</b><button id="qty-plus" type="button">+</button></div><div class="detail-actions"><button class="button button-dark" id="detail-add" ${p.stock<1?'disabled':''}>ব্যাগে যোগ করুন <span>↗</span></button><button class="button button-outline" id="detail-buy" ${p.stock<1?'disabled':''}>এখনই অর্ডার করুন</button></div><div class="pay-note">COD · bKash · Nagad · Rocket · Card</div></div></section><section class="related-section"><span class="eyebrow">আপনার জন্য আরও</span><h2>সম্পর্কিত পণ্য</h2><div class="related-grid">${related.map(r=>`<button class="related-item" data-related="${r.id}">${productImage(r)}<span>${esc(r.title)}</span><b>${fmt(r.price)}</b></button>`).join('')||'<span>আরও পণ্য শীঘ্রই আসছে।</span>'}</div></section></main>${storeFooter(state.config)}${contactRail()}<div id="modal-root"></div>`;
    bindContactWidget();let qty=1;const qtyText=()=>document.querySelector('#detail-qty').textContent=qty;
    document.querySelector('#open-cart')?.addEventListener('click',openCart);
    document.querySelector('#qty-minus').onclick=()=>{qty=Math.max(1,qty-1);qtyText()};document.querySelector('#qty-plus').onclick=()=>{qty=Math.min(Number(p.stock)||99,qty+1);qtyText()};
    document.querySelector('#detail-add').onclick=()=>{addCart(p,qty);toast('ব্যাগে যোগ হয়েছে')};
    document.querySelector('#detail-buy').onclick=()=>checkout([{id:p.id,title:p.title,price:p.price,quantity:qty}]);
    document.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>openProduct(Number(b.dataset.related)));
    window.scrollTo({top:0,behavior:'instant'});
  }catch(e){toast(e.message)}
}
function addCart(p,quantity=1){const row=state.cart.find(x=>x.id===p.id);if(row)row.quantity=Math.min(Number(p.stock)||99,row.quantity+quantity);else state.cart.push({id:p.id,title:p.title,price:p.price,image_url:p.image_url,category_slug:p.category_slug,quantity});saveCart();document.querySelector('#open-cart b')&&(document.querySelector('#open-cart b').textContent=cartCount())}
function openCart(){
  const contents=()=>{const rows=state.cart.map((x,i)=>`<div class="cart-row"><div class="cart-thumb">${productImage(x)}</div><div class="cart-row-info"><strong>${esc(x.title)}</strong><span>${fmt(x.price)}</span><div class="cart-qty"><button data-q="${i}" data-step="-1">−</button><b>${x.quantity}</b><button data-q="${i}" data-step="1">+</button></div></div><button class="remove-item" data-remove="${i}" aria-label="Remove">×</button></div>`).join('');
    openModal(`<div class="cart-panel"><span class="eyebrow">আপনার নির্বাচন</span><h2>আপনার ব্যাগ <small>(${cartCount()})</small></h2>${rows||'<div class="cart-empty">ব্যাগ এখনো খালি।<br>পছন্দের পণ্য যোগ করুন।</div>'}<div class="cart-total"><span>পণ্যের subtotal</span><b>${fmt(cartTotal())}</b></div><p class="small-note">Delivery charge ঠিকানার ভিত্তিতে checkout-এ দেখানো হবে।</p><button class="button button-dark full-button" id="cart-checkout" ${rows?'':'disabled'}>Checkout করুন <span>↗</span></button><button class="text-button centered" id="continue-shopping">কেনাকাটা চালিয়ে যান</button></div>`);
    document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const x=state.cart[Number(b.dataset.q)];x.quantity=Math.max(1,x.quantity+Number(b.dataset.step));saveCart();contents()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.cart.splice(Number(b.dataset.remove),1);saveCart();contents()});document.querySelector('#cart-checkout').onclick=()=>{const items=[...state.cart];document.querySelector('#modal-root').innerHTML='';checkout(items)};document.querySelector('#continue-shopping').onclick=()=>document.querySelector('#modal-root').innerHTML='';
  };contents();
}
function checkout(items){
  const subtotal=items.reduce((n,x)=>n+x.price*x.quantity,0);const settings=state.config;
  openModal(`<form id="checkout-form" class="checkout-form"><div class="checkout-head"><span class="eyebrow">আপনার অর্ডার</span><h2>ডেলিভারি তথ্য</h2><p>সঠিক তথ্য দিন, আমরা আপনার সাথে যোগাযোগ করব।</p></div><div class="checkout-layout"><div class="checkout-fields"><div class="field-grid"><label>আপনার নাম<input name="name" required minlength="2" autocomplete="name" placeholder="পূর্ণ নাম"></label><label>মোবাইল নম্বর<input name="phone" required minlength="7" autocomplete="tel" placeholder="01XXXXXXXXX"></label></div><label>Email <span class="optional">ঐচ্ছিক</span><input type="email" name="email" autocomplete="email" placeholder="you@example.com"></label><label>সম্পূর্ণ ঠিকানা<textarea name="address" required minlength="8" autocomplete="street-address" placeholder="বাড়ি, রোড, এলাকা..."></textarea></label><label>শহর / জেলা<input name="area" placeholder="যেমন: ঢাকা"></label><fieldset class="payment-methods"><legend>পেমেন্ট পদ্ধতি নির্বাচন</legend>${[['cod','Cash on Delivery','ডেলিভারির সময় পরিশোধ'],['bkash','bKash',settings.payment_bkash?`Send Money · ${settings.payment_bkash}`:'Admin Settings-এ নম্বর সেট হবে'],['nagad','Nagad',settings.payment_nagad?`Send Money · ${settings.payment_nagad}`:'Admin Settings-এ নম্বর সেট হবে'],['rocket','Rocket',settings.payment_rocket?`Send Money · ${settings.payment_rocket}`:'Admin Settings-এ নম্বর সেট হবে'],['card','Credit / Debit Card',settings.payment_card_url?'Secure payment link':'Payment link Admin Settings-এ সেট হবে']].map(([id,title,desc],i)=>`<label class="payment-choice"><input type="radio" name="payment_method" value="${id}" ${i===0?'checked':''}><span class="radio-mark"></span><span><b>${title}</b><small>${esc(desc)}</small></span><span class="pay-brand pay-${id}">${id==='cod'?'COD':id==='card'?'VISA':id.toUpperCase()}</span></label>`).join('')}</fieldset><div id="proof-fields" class="proof-fields" hidden><div class="instruction-card"><b>পেমেন্ট করার পর</b><span>${esc(settings.payment_instructions||'Transaction code ও payment screenshot দিন। Admin যাচাই করার পর order confirm হবে।')}</span></div><label>Transaction / Reference code<input name="transaction_code" maxlength="100" placeholder="পেমেন্ট রসিদে থাকা কোড"></label><label class="file-drop">পেমেন্টের screenshot দিন <small>JPG, PNG অথবা WebP · সর্বোচ্চ 5 MB</small><input type="file" name="proof" accept="image/jpeg,image/png,image/webp"><span id="file-name">ফাইল বাছাই করুন</span></label></div><div class="form-error" id="checkout-error" role="alert"></div><button class="button button-dark full-button" type="submit">অর্ডার নিশ্চিত করুন <span>↗</span></button><p class="privacy-note">আপনার তথ্য শুধু অর্ডার পৌঁছে দেওয়ার জন্য ব্যবহার করা হবে।</p></div><aside class="order-summary"><span class="eyebrow">Order summary</span>${items.map(x=>`<div class="summary-item"><span>${esc(x.title)} × ${x.quantity}</span><b>${fmt(x.price*x.quantity)}</b></div>`).join('')}<div class="summary-item"><span>পণ্যের মূল্য</span><b>${fmt(subtotal)}</b></div><div class="summary-item"><span>Delivery</span><b>${fmt(settings.shipping_fee||0)}</b></div><div class="summary-total"><span>মোট</span><b>${fmt(subtotal+Number(settings.shipping_fee||0))}</b></div><small>Online payment review সম্পন্ন হলে order confirm হবে।</small></aside></div></form>`);
  const form=document.querySelector('#checkout-form');const radios=[...form.querySelectorAll('[name=payment_method]')];
  const refresh=()=>{const method=form.querySelector('[name=payment_method]:checked').value;const fields=document.querySelector('#proof-fields');fields.hidden=method==='cod';fields.querySelector('[name=transaction_code]').required=method!=='cod';fields.querySelector('[name=proof]').required=method!=='cod';const extra=method==='bkash'?settings.payment_bkash:method==='nagad'?settings.payment_nagad:method==='rocket'?settings.payment_rocket:'';const instruction=fields.querySelector('.instruction-card');if(method==='card'&&safeUrl(settings.payment_card_url)){instruction.innerHTML=`<b>Card payment</b><span>Secure hosted payment page-এ payment শেষ করে screenshot ও reference দিন।</span><a href="${esc(safeUrl(settings.payment_card_url))}" target="_blank" rel="noopener">Secure payment link খুলুন ↗</a>`}else{instruction.innerHTML=`<b>${method==='cod'?'':'পেমেন্ট করার পর'}</b><span>${extra?`${esc(method.toUpperCase())} Send Money: ${esc(extra)} · `:''}${esc(settings.payment_instructions||'Transaction code ও payment screenshot দিন। Admin যাচাই করার পর order confirm হবে।')}</span>`}};radios.forEach(r=>r.onchange=refresh);refresh();
  form.querySelector('[name=proof]').onchange=e=>{document.querySelector('#file-name').textContent=e.target.files[0]?.name||'ফাইল বাছাই করুন'};
  form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('[type=submit]');btn.disabled=true;btn.textContent='অর্ডার পাঠানো হচ্ছে…';document.querySelector('#checkout-error').textContent='';const fd=new FormData(form);const order={name:fd.get('name'),phone:fd.get('phone'),email:fd.get('email'),address:fd.get('address'),area:fd.get('area'),payment_method:fd.get('payment_method'),transaction_code:fd.get('transaction_code'),items:items.map(x=>({id:x.id,quantity:x.quantity}))};const request=new FormData();request.append('order',JSON.stringify(order));if(fd.get('proof')?.size)request.append('proof',fd.get('proof'));try{const result=await api('/api/orders',{method:'POST',body:request});state.cart=[];saveCart();document.querySelector('#modal-root').innerHTML='';document.querySelector('#open-cart b')&&(document.querySelector('#open-cart b').textContent='0');orderSuccess(result)}catch(err){document.querySelector('#checkout-error').textContent=err.message;btn.disabled=false;btn.innerHTML='আবার চেষ্টা করুন <span>↗</span>'}};
}
function orderSuccess(r){openModal(`<div class="success-card"><span class="success-icon">✓</span><span class="eyebrow">Order received</span><h2>ধন্যবাদ! অর্ডার জমা হয়েছে।</h2><p>আপনার Order ID <b>${esc(r.order_no)}</b></p><p>${r.payment_status==='review_pending'?'Payment proof Admin যাচাই করবেন। এরপর অর্ডার নিশ্চিত করা হবে।':'আমরা ফোনে অর্ডার নিশ্চিত করব।'}</p><div class="success-total"><span>Order total</span><b>${fmt(r.total)}</b></div><button class="button button-dark full-button" id="done">দোকানে ফিরে যান</button></div>`);document.querySelector('#done').onclick=()=>{document.querySelector('#modal-root').innerHTML='';loadStore()}}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),2300)}
document.addEventListener('submit',e=>{if(e.target?.id==='newsletter-form'){e.preventDefault();toast('Newsletter সাইন-আপ শিগগিরই চালু হবে')}});

async function renderAdmin(){
  if(location.hash!=='#admin')location.hash='admin';
  app.innerHTML='<main class="admin-loading">Admin panel খোলা হচ্ছে…</main>';
  try{const status=await api('/api/admin/status');try{const me=await api('/api/admin/me');state.admin=true;state.adminEmail=me.email;await renderDashboard()}catch{state.admin=false;renderAdminAuth(status)}}catch(e){app.innerHTML=`<main class="offline"><h1>Admin API unavailable</h1><p>${esc(e.message)}</p></main>`}
}
function renderAdminAuth(status){
  const setup=status.needs_setup;app.innerHTML=`<main class="admin-auth"><a class="brand" href="#home"><span class="brand-mark">NL</span><span><strong>${esc(state.config.store_name||'নওয়াব লুম')}</strong><small>ADMIN CONSOLE</small></span></a><section class="auth-card"><span class="eyebrow">SECURE ADMIN</span><h1>${setup?'প্রথম Admin account তৈরি করুন':'Admin sign in'}</h1><p>${setup?'প্রথমবার account তৈরিতে একবার Bootstrap key লাগবে। এরপর login-এ শুধু email ও password লাগবে।':'Store পরিচালনা করতে email ও password দিয়ে sign in করুন।'}</p><form id="admin-auth-form">${setup?'<label>Bootstrap key<input name="bootstrap" type="password" required autocomplete="off"></label>':''}<label>Admin email<input name="email" type="email" required autocomplete="username" placeholder="admin@yourstore.com"></label><label>Password<input name="password" type="password" required ${setup?'minlength="12"':'autocomplete="current-password"'} autocomplete="new-password"></label><div class="form-error" id="auth-error"></div><button class="button button-dark full-button">${setup?'Admin account তৈরি করুন':'Sign in'} <span>↗</span></button></form><a href="#home" class="text-button centered">← Store-এ ফিরে যান</a></section></main>`;
  document.querySelector('#admin-auth-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget);const body={email:d.get('email'),password:d.get('password')};try{const url=setup?'/api/admin/bootstrap':'/api/admin/login';const options=jsonOptions(body);if(setup)options.headers['X-Bootstrap-Key']=d.get('bootstrap');await api(url,options);state.admin=true;state.adminEmail=body.email;renderDashboard()}catch(err){document.querySelector('#auth-error').textContent=err.message}};
}
async function renderDashboard(){
  const [orders,products,cats,report,demand,settings]=await Promise.all([api('/api/admin/orders'),api('/api/admin/products'),api('/api/admin/categories'),api(`/api/admin/reports?day=${bdDate()}`),api('/api/admin/demand'),api('/api/config')]);
  state.adminOrders=orders.orders;state.adminProducts=products.products;state.adminCategories=cats.categories;state.daily=report;state.demand=demand;state.config=settings;
  const tabs=[['overview','Overview','▦'],['orders','Orders','▤'],['products','Products','◇'],['categories','Categories','◈'],['demand','Demand','↗'],['daily','Daily report','▥'],['settings','Store settings','⚙'],['account','Admin account','◎']];
  app.innerHTML=`<div class="admin-layout"><aside class="admin-sidebar"><a class="brand" href="#home"><span class="brand-mark">NL</span><span><strong>${esc(settings.store_name||'নওয়াব লুম')}</strong><small>ADMIN CONSOLE</small></span></a><nav>${tabs.map(([id,label,icon])=>`<button class="admin-nav ${state.adminTab===id?'selected':''}" data-admin-tab="${id}"><span>${icon}</span>${label}</button>`).join('')}</nav><div class="admin-user"><span class="admin-avatar">${esc((state.adminEmail[0]||'A').toUpperCase())}</span><span><b>${esc(state.adminEmail)}</b><small>Store administrator</small></span><button id="admin-logout" title="Sign out">↗</button></div></aside><main class="admin-main"><header class="admin-topbar"><div><span class="eyebrow">STORE MANAGEMENT</span><h1>${esc(tabs.find(x=>x[0]===state.adminTab)?.[1]||'Overview')}</h1></div><div class="admin-top-actions"><a href="#home" target="_blank">Store দেখুন ↗</a><span class="live-pill"><i></i> LIVE STORE</span></div></header><section id="admin-content">${adminTabMarkup()}</section></main></div>`;
  document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminTab;renderDashboard()});document.querySelector('#admin-logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'});state.admin=false;renderAdmin()};bindAdminTab();
}
function adminTabMarkup(){
  const d=state.daily;const demand=state.demand;const orderCount=demand.summary?.order_count||0;const waiting=state.adminOrders.filter(o=>o.payment_status==='review_pending').length;
  if(state.adminTab==='overview')return `<div class="stat-grid"><article><span>আজকের অর্ডার</span><b>${d.summary?.order_count||0}</b><small>আজ জমা হয়েছে</small></article><article><span>আজকের অর্ডার মূল্য</span><b>${fmt(d.summary?.order_value||0)}</b><small>বাতিল বাদে</small></article><article><span>Payment review</span><b>${waiting}</b><small>যাচাই বাকি</small></article><article><span>সক্রিয় পণ্য</span><b>${state.adminProducts.filter(p=>p.active).length}</b><small>দুই ক্যাটাগরি জুড়ে</small></article></div><div class="admin-columns"><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">LATEST</span><h2>সাম্প্রতিক অর্ডার</h2></div><button class="text-button" data-admin-tab="orders">সব অর্ডার →</button></div>${state.adminOrders.slice(0,6).map(orderRow).join('')||'<p class="admin-empty">এখনো কোনো অর্ডার নেই।</p>'}</section><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">TOP SELLERS · ALL TIME</span><h2>চাহিদার পণ্য</h2></div></div>${(demand.top_selling||[]).slice(0,6).map(x=>`<div class="demand-row"><span>${esc(x.product_title)}</span><b>${x.units} pcs</b><small>${fmt(x.sales)}</small></div>`).join('')||'<p class="admin-empty">এখনো বিক্রির তথ্য আসেনি।</p>'}</section></div><div class="admin-card notice-card"><b>${orderCount}টি মোট অর্ডার</b><span>Order, payment proof, product catalog, demand এবং daily PDF রিপোর্ট menu থেকে পরিচালনা করুন।</span></div>`;
  if(state.adminTab==='orders')return `<div class="admin-toolbar"><div><b>${state.adminOrders.length} orders</b><span>· সর্বশেষ 500টি</span></div><button class="button button-outline" id="refresh-admin">↻ Refresh</button></div><div class="order-list">${state.adminOrders.map(orderRow).join('')||'<p class="admin-empty">অর্ডার জমা হলে এখানে দেখা যাবে।</p>'}</div>`;
  if(state.adminTab==='products')return `<div class="admin-toolbar"><div><b>${state.adminProducts.length} products</b><span>· saree ও lungi catalog</span></div><button class="button button-dark" id="add-product">+ নতুন পণ্য</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>পণ্য</th><th>ক্যাটাগরি</th><th>দাম</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>${state.adminProducts.map(p=>`<tr><td><b>${esc(p.title)}</b><small>${esc(p.slug)}</small></td><td>${esc(p.category_name)}</td><td>${fmt(p.price)}</td><td>${p.stock}</td><td>${p.active?'Active':'Hidden'}</td><td><button class="table-action" data-edit-product="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;
  if(state.adminTab==='categories')return `<div class="admin-toolbar"><div><b>${state.adminCategories.length} categories</b><span>· আলাদা saree ও lungi বিভাগ</span></div><button class="button button-dark" id="add-category">+ নতুন category</button></div><div class="category-admin-grid">${state.adminCategories.map(c=>`<article><span class="eyebrow">${c.active?'ACTIVE':'HIDDEN'}</span><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><small>/${esc(c.slug)}</small><button class="text-button" data-edit-category="${c.id}">Edit category →</button></article>`).join('')}</div>`;
  if(state.adminTab==='demand')return `<div class="stat-grid"><article><span>মোট অর্ডার</span><b>${demand.summary?.order_count||0}</b><small>সকল দিনের orders</small></article><article><span>মোট অর্ডার মূল্য</span><b>${fmt(demand.summary?.order_value||0)}</b><small>বাতিল বাদে</small></article><article><span>পেমেন্ট নিশ্চিত</span><b>${fmt(demand.summary?.paid_revenue||0)}</b><small>Verified / delivered</small></article><article><span>বাতিল / প্রত্যাখ্যাত</span><b>${demand.summary?.rejected_count||0}</b><small>সকল দিনের orders</small></article></div><div class="admin-columns"><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">BEST SELLERS · ALL TIME</span><h2>সবচেয়ে বেশি order ও sale</h2></div></div>${(demand.top_selling||[]).map(x=>`<div class="demand-row"><span>${esc(x.product_title)}</span><b>${x.units} pcs</b><small>${fmt(x.sales)}</small></div>`).join('')||'<p class="admin-empty">এখনো বিক্রির তথ্য আসেনি।</p>'}</section><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">REJECTED / CANCELLED</span><h2>বাতিল বা প্রত্যাখ্যাত পণ্য</h2></div></div>${(demand.rejected||[]).map(x=>`<div class="demand-row"><span>${esc(x.product_title)}</span><b>${x.units} pcs</b><small>${x.orders} orders</small></div>`).join('')||'<p class="admin-empty">Rejected order নেই।</p>'}</section></div>`;
  if(state.adminTab==='daily')return `<div class="report-toolbar"><label>Dhaka-র তারিখ নির্বাচন<input type="date" id="report-day" value="${esc(d.day)}"></label><button class="button button-outline" id="download-pdf">PDF ডাউনলোড ↧</button></div><div class="stat-grid"><article><span>আজকের অর্ডার</span><b>${d.summary?.order_count||0}</b></article><article><span>মোট অর্ডার মূল্য</span><b>${fmt(d.summary?.order_value||0)}</b></article><article><span>পেমেন্ট নিশ্চিত</span><b>${fmt(d.summary?.paid_revenue||0)}</b></article><article><span>Rejected / Cancelled</span><b>${d.summary?.rejected_count||0}</b></article></div><div class="admin-columns"><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">BEST SELLERS · ${esc(d.day)}</span><h2>আজ বিক্রি হওয়া পণ্য</h2></div></div>${(d.top_selling||[]).map(x=>`<div class="demand-row"><span>${esc(x.product_title)}</span><b>${x.units} pcs</b><small>${fmt(x.sales)}</small></div>`).join('')||'<p class="admin-empty">এই দিনের বিক্রির তথ্য নেই।</p>'}</section><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">REJECTED</span><h2>বাতিল / প্রত্যাখ্যাত পণ্য</h2></div></div>${(d.rejected||[]).map(x=>`<div class="demand-row"><span>${esc(x.product_title)}</span><b>${x.units} pcs</b><small>${x.orders} orders</small></div>`).join('')||'<p class="admin-empty">Rejected order নেই।</p>'}</section></div><section class="admin-card"><div class="admin-card-head"><div><span class="eyebrow">DAILY ORDER DETAILS</span><h2>${esc(d.day)}-এর প্রতিটি অর্ডার</h2></div><span>${d.orders?.length||0} orders</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order & customer</th><th>পণ্য · পরিমাণ · একক দাম</th><th>Payment / status</th><th>মোট</th></tr></thead><tbody>${(d.orders||[]).map(o=>`<tr><td><b>${esc(o.order_no)}</b><small>${esc(o.customer_name)} · ${esc(o.phone)} · ${esc(o.address)} ${esc(o.area)}</small><small>${new Date(o.created_at).toLocaleTimeString('bn-BD')}</small></td><td>${(o.items||[]).map(i=>`<div>${esc(i.product_title)} × ${i.quantity} · ${fmt(i.unit_price)} = ${fmt(i.line_total)}</div>`).join('')}</td><td>${esc(o.payment_method.toUpperCase())}<small>${esc(o.payment_status)} · ${esc(o.status)}</small></td><td><b>${fmt(o.total)}</b></td></tr>`).join('')||'<tr><td colspan="4">এই তারিখে order নেই।</td></tr>'}</tbody></table></div></section>`;
  if(state.adminTab==='settings')return settingsMarkup();
  if(state.adminTab==='account')return `<form id="admin-account-form" class="admin-card settings-form"><div class="admin-card-head"><div><span class="eyebrow">SECURITY</span><h2>Admin email ও password</h2></div></div><label>বর্তমান password<input type="password" name="current_password" required autocomplete="current-password"></label><label>নতুন admin email<input type="email" name="email" value="${esc(state.adminEmail)}" required autocomplete="email"></label><label>নতুন password <small>পরিবর্তন না করলে ফাঁকা রাখুন; দিলে অন্তত ১২ অক্ষর</small><input type="password" name="password" minlength="12" autocomplete="new-password"></label><div class="form-error" id="admin-form-error"></div><button class="button button-dark">নিরাপত্তা তথ্য update করুন</button></form>`;
  return '';
}
function orderRow(o){
  const statusLabel={pending:'নতুন',awaiting_payment_review:'পেমেন্ট যাচাই বাকি',processing:'প্রসেসিং',shipped:'পাঠানো হয়েছে',delivered:'ডেলিভারড',cancelled:'বাতিল',rejected:'প্রত্যাখ্যাত'}[o.status]||o.status;
  const final=['cancelled','rejected','delivered'].includes(o.status);const review=o.payment_status==='review_pending';
  const controls=final?'':review?`<button class="button button-dark mini" data-verify="${o.id}">Payment verify</button><button class="table-action danger" data-reject="${o.id}">Reject payment</button><button class="table-action danger" data-cancel="${o.id}">Cancel order</button>`:`<button class="table-action" data-process="${o.id}">Process</button><button class="table-action" data-ship="${o.id}">Shipped</button><button class="table-action" data-deliver="${o.id}">Delivered</button><button class="table-action danger" data-cancel="${o.id}">Cancel</button>`;
  return `<article class="order-card"><div class="order-card-top"><div><span class="eyebrow">${esc(o.order_no)} · ${new Date(o.created_at).toLocaleString('bn-BD')}</span><h3>${esc(o.customer_name)} <small>${esc(o.phone)}</small></h3><p>${esc(o.address)} ${esc(o.area)}</p></div><div class="order-total"><b>${fmt(o.total)}</b><span class="status-pill status-${esc(o.status)}">${statusLabel}</span></div></div><div class="order-items">${(o.items||[]).map(i=>`<span>${esc(i.product_title)} × ${i.quantity}</span>`).join('')}</div><div class="order-card-bottom"><span class="payment-summary">${esc(o.payment_method.toUpperCase())} · ${esc(o.payment_status)} ${o.transaction_code?`· Ref ${esc(o.transaction_code)}`:''}</span><div class="order-actions">${o.proof_key?`<button class="table-action" data-proof="${o.id}">Screenshot দেখুন</button>`:''}${controls}</div></div>${o.admin_note?`<p class="admin-note">Admin note: ${esc(o.admin_note)}</p>`:''}</article>`;
}
function settingsMarkup(){const c=state.config;const fields=[['store_name','Store name'],['tagline','Tagline'],['about','About the Store'],['phone','Call phone'],['whatsapp','WhatsApp number (country code সহ)'],['facebook','Facebook URL'],['instagram','Instagram URL'],['email','Store email'],['address','Store address'],['shipping_fee','Delivery charge (৳)'],['payment_bkash','bKash merchant/personal number'],['payment_nagad','Nagad number'],['payment_rocket','Rocket number'],['payment_card_url','Card payment secure URL'],['payment_instructions','Payment instruction']];return `<form id="settings-form" class="settings-form"><div class="settings-intro"><span class="eyebrow">CUSTOMIZE STORE</span><h2>দোকানের তথ্য ও পেমেন্ট</h2><p>এখানে নম্বর ও links save করলে storefront-এ দেখাবে। Payment screenshot admin review ছাড়া order confirm হয় না।</p></div><div class="settings-grid">${fields.map(([k,l])=>`<label class="${['about','payment_instructions'].includes(k)?'span-2':''}">${l}${['about','payment_instructions'].includes(k)?`<textarea name="${k}" rows="3">${esc(c[k]||'')}</textarea>`:`<input name="${k}" value="${esc(c[k]||'')}" ${k==='shipping_fee'?'type="number" min="0"':''} ${['email'].includes(k)?'type="email"':''}>`}</label>`).join('')}</div><div class="form-error" id="settings-error"></div><button class="button button-dark">Settings save করুন</button></form>`}

function bindAdminTab(){
  document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminTab;renderDashboard()});
  document.querySelector('#refresh-admin')?.addEventListener('click',renderDashboard);
  document.querySelector('#report-day')?.addEventListener('change',async e=>{state.daily=await api(`/api/admin/reports?day=${e.target.value}`);document.querySelector('#admin-content').innerHTML=adminTabMarkup();bindAdminTab()});
  document.querySelector('#download-pdf')?.addEventListener('click',downloadReport);
  document.querySelector('#add-product')?.addEventListener('click',()=>productEditor());document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productEditor(state.adminProducts.find(p=>p.id===Number(b.dataset.editProduct))));
  document.querySelector('#add-category')?.addEventListener('click',()=>categoryEditor());document.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>categoryEditor(state.adminCategories.find(c=>c.id===Number(b.dataset.editCategory))));
  document.querySelector('#settings-form')?.addEventListener('submit',saveSettings);document.querySelector('#admin-account-form')?.addEventListener('submit',saveAdminAccount);
  document.querySelectorAll('[data-proof]').forEach(b=>b.onclick=()=>showProof(Number(b.dataset.proof)));
  document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>updateOrder(Number(b.dataset.cancel),'cancelled'));
  document.querySelectorAll('[data-process]').forEach(b=>b.onclick=()=>updateOrder(Number(b.dataset.process),'processing','due_on_delivery'));
  document.querySelectorAll('[data-ship]').forEach(b=>b.onclick=()=>{const o=state.adminOrders.find(x=>x.id===Number(b.dataset.ship));updateOrder(o.id,'shipped',o.payment_status)});
  document.querySelectorAll('[data-deliver]').forEach(b=>b.onclick=()=>{const o=state.adminOrders.find(x=>x.id===Number(b.dataset.deliver));updateOrder(o.id,'delivered',o.payment_status)});
  document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=()=>updateOrder(Number(b.dataset.verify),'processing','verified'));
  document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>updateOrder(Number(b.dataset.reject),'rejected','rejected'));
}
async function updateOrder(id,status,payment_status){try{await api(`/api/admin/orders/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status,...(payment_status?{payment_status}:{})})});toast('Order update হয়েছে');renderDashboard()}catch(e){toast(e.message)}}
async function showProof(id){try{const r=await fetch(`/api/admin/orders/${id}/proof`,{credentials:'same-origin'});if(!r.ok)throw new Error('Screenshot খুলতে পারেনি');const blob=await r.blob();const url=URL.createObjectURL(blob);openModal(`<div class="proof-preview"><span class="eyebrow">PAYMENT PROOF · ORDER ${id}</span><img src="${url}" alt="Payment proof"></div>`)}catch(e){toast(e.message)}}
function productEditor(p={}){const edit=Boolean(p.id);openModal(`<form class="editor-form" id="product-form"><span class="eyebrow">CATALOG</span><h2>${edit?'পণ্য edit করুন':'নতুন পণ্য যোগ করুন'}</h2><label>পণ্যের নাম<input name="title" required value="${esc(p.title||'')}"></label><label>Category<select name="category_id" required>${state.adminCategories.map(c=>`<option value="${c.id}" ${p.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>বিস্তারিত<textarea name="description" rows="3">${esc(p.description||'')}</textarea></label><div class="field-grid"><label>দাম (৳)<input type="number" name="price" required min="0" value="${p.price??''}"></label><label>আগের দাম<input type="number" name="compare_at" min="0" value="${p.compare_at||''}"></label></div><div class="field-grid"><label>Stock<input type="number" name="stock" required min="0" value="${p.stock??0}"></label><label>Image HTTPS URL<input type="url" name="image_url" value="${esc(p.image_url||'')}" placeholder="https://..."></label></div>${edit?`<label>Slug<input name="slug" value="${esc(p.slug)}" required></label>`:''}<label class="check-line"><input type="checkbox" name="featured" ${p.featured?'checked':''}> Featured product</label>${edit?`<label class="check-line"><input type="checkbox" name="active" ${p.active?'checked':''}> Storefront-এ দেখান</label>`:''}<div id="editor-error" class="form-error"></div><button class="button button-dark full-button">${edit?'Update product':'পণ্য যোগ করুন'}</button></form>`);
  document.querySelector('#product-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const title=fd.get('title');const body={title,slug:fd.get('slug')||slugify(title),category_id:Number(fd.get('category_id')),description:fd.get('description'),price:Number(fd.get('price')),compare_at:fd.get('compare_at')||null,stock:Number(fd.get('stock')),image_url:fd.get('image_url'),featured:fd.has('featured'),active:fd.has('active')};try{await api(edit?`/api/admin/products/${p.id}`:'/api/admin/products',{method:edit?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});document.querySelector('#modal-root').innerHTML='';toast('পণ্য save হয়েছে');renderDashboard()}catch(err){document.querySelector('#editor-error').textContent=err.message}};
}
function slugify(s){return String(s).toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`item-${Date.now()}`}
function categoryEditor(c={}){const edit=Boolean(c.id);openModal(`<form class="editor-form" id="category-form"><span class="eyebrow">COLLECTION</span><h2>${edit?'Category edit':'নতুন category'}</h2><label>নাম<input name="name" value="${esc(c.name||'')}" required></label><label>Slug<input name="slug" value="${esc(c.slug||'')}" placeholder="saree / lungi" required></label><label>বর্ণনা<input name="description" value="${esc(c.description||'')}"></label><label>ক্রম<input type="number" name="sort_order" value="${c.sort_order||0}"></label>${edit?`<label class="check-line"><input type="checkbox" name="active" ${c.active?'checked':''}> সক্রিয়</label>`:''}<div class="form-error" id="editor-error"></div><button class="button button-dark full-button">Save category</button></form>`);document.querySelector('#category-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const body={name:fd.get('name'),slug:fd.get('slug'),description:fd.get('description'),sort_order:Number(fd.get('sort_order')),active:edit?fd.has('active'):true};try{await api(edit?`/api/admin/categories/${c.id}`:'/api/admin/categories',{method:edit?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});document.querySelector('#modal-root').innerHTML='';toast('Category save হয়েছে');renderDashboard()}catch(err){document.querySelector('#editor-error').textContent=err.message}}}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.currentTarget);const body=Object.fromEntries(f.entries());try{await api('/api/admin/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});toast('Store settings save হয়েছে');renderDashboard()}catch(err){document.querySelector('#settings-error').textContent=err.message}}
async function saveAdminAccount(e){e.preventDefault();const f=new FormData(e.currentTarget);const body=Object.fromEntries(f.entries());try{const r=await api('/api/admin/me',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});state.adminEmail=r.email;toast('Admin account update হয়েছে');renderDashboard()}catch(err){document.querySelector('#admin-form-error').textContent=err.message}}
async function downloadReport(){
  const [{jsPDF},{default:html2canvas}]=await Promise.all([import('jspdf'),import('html2canvas')]);
  const d=state.daily;const best=d.top_selling||[];const rejected=d.rejected||[];const orders=d.orders||[];const pageRows=10;
  const productPages=Math.max(1,Math.ceil(Math.max(best.length,rejected.length,1)/pageRows));const pageHtml=[];
  for(let page=0;page<productPages;page++){
    const bestRows=best.slice(page*pageRows,(page+1)*pageRows);const rejectedRows=rejected.slice(page*pageRows,(page+1)*pageRows);
    pageHtml.push(`<div style="font:600 20px 'Noto Serif Bengali',serif;color:#344b3d">${esc(state.config.store_name||'নওয়াব লুম')} · দৈনিক অর্ডার রিপোর্ট</div><div style="font:12px 'DM Sans',sans-serif;color:#727b75;margin:8px 0 22px">তারিখ: ${esc(d.day)} · Asia/Dhaka</div><div style="display:flex;gap:24px;padding:14px 0;border-block:1px solid #e8e9e3;font:13px 'Noto Serif Bengali',serif"><span>অর্ডার: <b>${d.summary?.order_count||0}</b></span><span>অর্ডার মূল্য: <b>${fmt(d.summary?.order_value||0)}</b></span><span>পেমেন্ট নিশ্চিত: <b>${fmt(d.summary?.paid_revenue||0)}</b></span><span>বাতিল: <b>${d.summary?.rejected_count||0}</b></span></div><h2 style="font:600 15px 'Noto Serif Bengali',serif;color:#344b3d;margin:22px 0 8px">সবচেয়ে বেশি অর্ডার / বিক্রিত পণ্য</h2>${bestRows.map((x,i)=>`<div class="pdf-row"><span>${page*pageRows+i+1}. ${esc(x.product_title)}</span><b>${x.units}টি</b><span>${fmt(x.sales)}</span></div>`).join('')||'<p>এই দিনে বিক্রির তথ্য নেই।</p>'}<h2 style="font:600 15px 'Noto Serif Bengali',serif;color:#344b3d;margin:20px 0 8px">বাতিল / প্রত্যাখ্যাত পণ্য</h2>${rejectedRows.map((x,i)=>`<div class="pdf-row"><span>${page*pageRows+i+1}. ${esc(x.product_title)}</span><b>${x.units}টি</b><span>${x.orders}টি order</span></div>`).join('')||'<p>বাতিল / প্রত্যাখ্যাত order নেই।</p>'}`);
  }
  for(const o of orders){const lines=(o.items||[]).map((i,n)=>`<div class="pdf-row"><span>${n+1}. ${esc(i.product_title)} × ${i.quantity}</span><b>${fmt(i.unit_price)}</b><span>${fmt(i.line_total)}</span></div>`).join('');pageHtml.push(`<div style="font:600 19px 'Noto Serif Bengali',serif;color:#344b3d">${esc(state.config.store_name||'নওয়াব লুম')} · Order details</div><div style="font:12px 'DM Sans',sans-serif;color:#727b75;margin:7px 0 18px">${esc(o.order_no)} · ${new Date(o.created_at).toLocaleString('bn-BD')}</div><div class="pdf-order-info"><b>গ্রাহক:</b> ${esc(o.customer_name)} · ${esc(o.phone)}<br><b>Email:</b> ${esc(o.email||'—')}<br><b>ঠিকানা:</b> ${esc(o.address)} ${esc(o.area)}<br><b>Payment:</b> ${esc(o.payment_method.toUpperCase())} · ${esc(o.payment_status)} · ${esc(o.status)}<br><b>Transaction:</b> ${esc(o.transaction_code||'—')}</div><h2 style="font:600 15px 'Noto Serif Bengali',serif;color:#344b3d;margin:22px 0 8px">অর্ডার করা পণ্য · একক দাম · line total</h2>${lines}<div class="pdf-total"><span>পণ্যের মূল্য</span><b>${fmt(o.subtotal)}</b></div><div class="pdf-total"><span>ডেলিভারি</span><b>${fmt(o.shipping_fee)}</b></div><div class="pdf-total pdf-grand"><span>মোট</span><b>${fmt(o.total)}</b></div>`)}
  const images=[];for(let i=0;i<pageHtml.length;i++){const sheet=document.createElement('div');sheet.className='pdf-sheet';sheet.innerHTML=`${pageHtml[i]}<div class="pdf-footer">${esc(state.config.store_name||'নওয়াব লুম')} · ${i+1}/${pageHtml.length}</div>`;document.body.append(sheet);await document.fonts.ready;const canvas=await html2canvas(sheet,{scale:1.6,backgroundColor:'#fffefa',useCORS:true});images.push(canvas.toDataURL('image/png'));sheet.remove()}
  const doc=new jsPDF({unit:'mm',format:'a4'});images.forEach((img,i)=>{if(i)doc.addPage();doc.addImage(img,'PNG',0,0,210,297)});doc.save(`nawab-loom-daily-${d.day}.pdf`);
}

window.addEventListener('hashchange',()=>location.hash==='#admin'?renderAdmin():loadStore());
window.addEventListener('popstate',()=>location.hash==='#admin'?renderAdmin():loadStore());
if(location.hash==='#admin')renderAdmin();else loadStore();
